                direction = 1
                i += 1
        elif direction == 1:  # moving down
            if i < R - 1:
                i += 1
            else:
                direction = 2
                j -= 1
        elif direction == 2:  # moving left
            if j > 0:
                j -= 1
            else:
                direction = 3
                i -= 1
        elif direction == 3:  # moving up
            if i > 0:
                i -= 1
            else:
                direction = 0
                j += 1

        K -= 1

    return grey_count

