def count_grey_squares(R, C, K):
    def has_ones_in_same_position(x, y):
        return any((x >> i) & (y >> i) for i in range(32))

    def count_greys_in_row(row):
        x = row << 32 | (row + 1)
        count = 0
        while x > 0:
            if has_ones_in_same_position(row, x):
                count += bin(x).count('1')
            x >>= 1
        return count

    grey_count = 0
    for i in range(min(K, R)):
        grey_count += count_greys_in_row(i)
        if i < C:
            grey_count += count_greys_in_row(i)
    return min(grey_count, K)

