def count_grey_squares(R, C, K):
    def is_gray(row, col):
        bin_row = bin(row)[2:]
        bin_col = bin(col)[2:]
        return any(b == '1' for b in zip(bin_row.zfill(max(len(bin_row), len(bin_col))), bin_col.zfill(max(len(bin_row), len(bin_col)))))

    count = 0
    row, col = 0, 0
    direction = 1  # 1 for right, -1 for left
    for _ in range(K):
        if is_gray(row, col):
            count += 1
        if (direction == 1 and col == C - 1) or (direction == -1 and col == 0):
            direction *= -1
            if direction == 1:
                row += 1
            else:
                row -= 1
        else:
            col += direction
    return count

